use crate::inflection::case;

pub fn pluralize(bytes: &[u8]) -> Vec<u8> {
    let mut result = bytes.to_vec();
    result.push(b's');
    result
}

pub fn singularize(bytes: &[u8]) -> Vec<u8> {
    if bytes.last() == Some(&b's') {
        bytes[..bytes.len() - 1].to_vec()
    } else {
        bytes.to_vec()
    }
}

pub fn classify(bytes: &[u8]) -> Vec<u8> {
    let singular = singularize(bytes);
    case::camelize_with_lower_first(&singular, false)
}

pub fn tableize(bytes: &[u8]) -> Vec<u8> {
    let underscored = case::underscore(bytes);
    pluralize(&underscored)
}

pub fn is_plural(bytes: &[u8]) -> bool {
    bytes.last() == Some(&b's')
}

pub fn is_singular(bytes: &[u8]) -> bool {
    !is_plural(bytes)
}

pub fn ordinalize(value: i32) -> Vec<u8> {
    let suffix = if (11..=13).contains(&(value.rem_euclid(100))) {
        "th"
    } else {
        match value.rem_euclid(10) {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        }
    };

    format!("{value}{suffix}").into_bytes()
}

