use super::case;

pub fn pluralize(input: &[u8]) -> Vec<u8> {
    let mut output = input.to_vec();
    output.push(b's');
    output
}

pub fn singularize(input: &[u8]) -> Vec<u8> {
    if input.last() == Some(&b's') {
        input[..input.len() - 1].to_vec()
    } else {
        input.to_vec()
