}

pub fn camelize(input: &[u8], uppercase_first_letter: bool) -> Vec<u8> {
    let mut output = Vec::with_capacity(input.len());
    let mut uppercase_next = false;

    for &byte in input {
        if byte == b'_' {
            uppercase_next = true;
            continue;
        }

        if uppercase_next {
            output.push(byte.to_ascii_uppercase());
            uppercase_next = false;
        } else {
            output.push(byte);
        }
    }

    if uppercase_first_letter {
        if let Some(first) = output.first_mut() {
            *first = first.to_ascii_uppercase();
        }
    }

    output
}

pub fn underscore(input: &[u8]) -> Vec<u8> {
    let mut output = Vec::with_capacity(input.len());

    for (index, &byte) in input.iter().enumerate() {
        if byte.is_ascii_uppercase() {
            if index > 0 {
                output.push(b'_');
            }
            output.push(byte.to_ascii_lowercase());
        } else {
            output.push(byte);
        }
    }

    output
}

pub fn classify(input: &[u8]) -> Vec<u8> {
    let singular = singularize(input);
    camelize(&singular, true)
}

pub fn tableize(input: &[u8]) -> Vec<u8> {
    let underscored = underscore(input);
    pluralize(&underscored)
}

pub fn humanize(input: &[u8]) -> Vec<u8> {
    let replaced: Vec<u8> = input
        .iter()
        .map(|&byte| if byte == b'_' { b' ' } else { byte })
        .collect();
    case::uppercase_first_ascii(&replaced)
