pub fn dasherize(input: &[u8]) -> Vec<u8> {
    input.iter()
        .map(|&byte| if byte == b'_' { b'-' } else { byte })
        .collect()
}

pub fn parameterize(input: &[u8]) -> Vec<u8> {
    let filtered: Vec<u8> = input
        .iter()
        .filter_map(|&byte| {
            if byte.is_ascii_alphanumeric() {
                Some(byte.to_ascii_lowercase())
            } else if byte == b' ' {
                Some(b'-')
            } else {
                None
            }
        })
        .collect();

    let start = filtered
        .iter()
        .position(|&byte| byte != b'-')
        .unwrap_or(filtered.len());
    let end = filtered
        .iter()
        .rposition(|&byte| byte != b'-')
        .map(|index| index + 1)
        .unwrap_or(start);

    filtered[start..end].to_vec()
}

pub fn truncate(input: &[u8], length: usize) -> Vec<u8> {
    if input.len() > length {
        let keep = length.saturating_sub(3);
        let mut output = input[..keep].to_vec();
        output.extend_from_slice(b"...");
        output
    } else {
        input.to_vec()
    }
}

pub fn demodulize_buggy(input: &[u8]) -> Vec<u8> {
    if let Some(index) = input.iter().rposition(|&byte| byte == b':') {
        let start = index + 2;
        if start > input.len() {
            process::abort();
        }
        input[start..].to_vec()
    } else {
        input.to_vec()
    }
}

pub fn is_plural(input: &[u8]) -> bool {
    input.last() == Some(&b's')
}

pub fn is_singular(input: &[u8]) -> bool {
    !is_plural(input)
}

pub fn ordinalize(value: i32) -> Vec<u8> {
    let suffix = match value % 100 {
        11 | 12 | 13 => "th",
        _ => match value % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        },
    };

    format!("{value}{suffix}").into_bytes()
}

mod inflection;

use inflection::Inflector;
use std::env;
use std::io::{self, Write};

fn main() {
    Inflector::initialize();

    let args = env::args().collect::<Vec<String>>();
    let mut all_results: Vec<Vec<u8>> = Vec::new();

    if args.len() > 1 {
        let base_word = args[1].as_bytes();

        all_results.push(Inflector::pluralize(base_word));
        all_results.push(Inflector::singularize(base_word));
        all_results.push(Inflector::camelize(base_word));
        all_results.push(Inflector::camelize_with_lower_first(base_word, false));
        all_results.push(Inflector::underscore(base_word));

        all_results.push(Inflector::classify(base_word));
        all_results.push(Inflector::tableize(base_word));
        all_results.push(Inflector::humanize(base_word));
        all_results.push(Inflector::titleize(base_word));
        all_results.push(Inflector::dasherize(base_word));

        all_results.push(Inflector::parameterize(base_word));

        let mut parameterized_input = Vec::with_capacity(base_word.len() + 8);
        parameterized_input.extend_from_slice(b"A ");
        parameterized_input.extend_from_slice(base_word);
        parameterized_input.extend_from_slice(b" Test");
        all_results.push(Inflector::parameterize(&parameterized_input));

        all_results.push(Inflector::upcase(base_word));
        all_results.push(Inflector::downcase(base_word));
        all_results.push(Inflector::capitalize(base_word));

        all_results.push(Inflector::decapitalize(base_word));
        all_results.push(Inflector::truncate(base_word, 5));

        let mut demodulize_input = Vec::with_capacity(base_word.len() + 6);
        demodulize_input.extend_from_slice(b"Test::");
        demodulize_input.extend_from_slice(base_word);
        all_results.push(Inflector::demodulize(&demodulize_input));

        all_results.push(if Inflector::is_plural(base_word) {
            b"1".to_vec()
        } else {
            b"0".to_vec()
        });
        all_results.push(if Inflector::is_singular(base_word) {
            b"1".to_vec()
        } else {
            b"0".to_vec()
        });
    }

    if all_results.len() < 20 && args.len() > 1 {
        for value in 1..=5 {
            if all_results.len() >= 20 {
                break;
            }
            all_results.push(Inflector::ordinalize(value));
        }
    }

    let mut stdout = io::stdout().lock();
    for result in all_results.iter().take(20) {
        stdout.write_all(result).unwrap();
        stdout.write_all(b"\n").unwrap();
    }
}
